public class DeleteSystemCommandHandler : IRequestHandler<DeleteSystemCommand, Result<int>>
{
    private readonly IApplicationDbContextFactory _dbContextFactory;

    public DeleteSystemCommandHandler(
        IApplicationDbContextFactory dbContextFactory
    )
    {
        _dbContextFactory = dbContextFactory;
    }

    public async Task<Result<int>> Handle(DeleteSystemCommand request, CancellationToken cancellationToken)
    {
        await using var db = await _dbContextFactory.CreateAsync(cancellationToken);
        var items = await db.Systems.Where(x => request.Id.Contains(x.Id)).ToListAsync(cancellationToken);
        
        if (items.Count == 0)
        {
            return await Result<int>.FailureAsync($"System(s) with id(s): {string.Join(",", request.Id)} not found.");
        }

        foreach (var item in items)
        {
            // Add domain event for audit purposes (AC 5: All system operations are logged)
            item.AddDomainEvent(new SystemDeletedEvent(item));
            db.Systems.Remove(item);
        }

        var result = await db.SaveChangesAsync(cancellationToken);
        return await Result<int>.SuccessAsync(result);
    }
